+            let buffer = terminal.backend().buffer();
+            for x in 3..(3 + title.len() as u16) {
+                assert_eq!(buffer[(x, 0)].fg, theme.text(), "{title} cell {x}");
+            }
+            if title == "Short" {
+                assert_eq!(buffer[(8, 0)].symbol(), " ");
